ALTER TABLE public.task_revisions ADD COLUMN visible_to_creator boolean NOT NULL DEFAULT false;
ALTER TABLE public.task_executions ADD COLUMN visible_to_creator boolean NOT NULL DEFAULT false, ADD COLUMN archived_at timestamptz, ADD COLUMN occurrence_date date;
UPDATE public.task_revisions r SET visible_to_creator=t.visible_to_creator FROM public.tasks t WHERE t.id=r.task_id;
UPDATE public.task_executions e SET visible_to_creator=t.visible_to_creator,occurrence_date=e.scheduled_date FROM public.tasks t WHERE t.id=e.task_id;
CREATE UNIQUE INDEX task_execution_occurrence_unique ON public.task_executions(task_id,occurrence_date) WHERE status<>'cancelled';
CREATE OR REPLACE FUNCTION public.can_read_execution(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_active_member(auth.uid()) AND EXISTS(SELECT 1 FROM public.task_executions e WHERE e.id=_id AND (public.is_executive() OR e.owner_id=auth.uid() OR (e.visible_to_creator AND public.is_own_creator(e.creator_id)))) $$;
REVOKE ALL ON FUNCTION public.can_read_execution(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.can_read_execution(uuid) TO authenticated;
DROP POLICY "execution own read" ON public.task_executions;
CREATE POLICY "execution own read" ON public.task_executions FOR SELECT TO authenticated USING(public.can_read_execution(id));
CREATE OR REPLACE FUNCTION public.can_see_task(_task_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_active_member(auth.uid()) AND EXISTS(SELECT 1 FROM public.tasks WHERE id=_task_id AND (public.is_executive() OR owner_id=auth.uid() OR (visible_to_creator AND public.is_own_creator(creator_id)))) $$;
CREATE OR REPLACE FUNCTION public.materialize_task_executions() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE today date := (now() AT TIME ZONE 'America/Bogota')::date; BEGIN
INSERT INTO public.task_executions(task_id,revision_id,scheduled_date,occurrence_date,due_time,title,description,owner_id,creator_id,priority,recurring,visible_to_creator)
SELECT r.task_id,r.id,d::date,d::date,r.due_time,r.title,r.description,r.owner_id,r.creator_id,r.priority,true,r.visible_to_creator FROM public.task_revisions r CROSS JOIN LATERAL generate_series(r.effective_from::timestamp,least(coalesce(r.effective_until,today),today)::timestamp,interval '1 day') d WHERE r.enabled AND r.recurrence<>'once' AND (r.recurrence='daily' OR extract(dow FROM d)::integer=ANY(r.weekdays)) ON CONFLICT DO NOTHING; END $$;
CREATE OR REPLACE FUNCTION public.task_agenda(_date date) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE today date := (now() AT TIME ZONE 'America/Bogota')::date; result jsonb; BEGIN
IF NOT public.is_active_member(auth.uid()) THEN RAISE EXCEPTION 'Not authorized'; END IF; PERFORM public.materialize_task_executions();
SELECT coalesce(jsonb_agg(to_jsonb(e)||jsonb_build_object('projected',false) ORDER BY e.scheduled_date,e.due_time),'[]'::jsonb) INTO result FROM public.task_executions e WHERE e.archived_at IS NULL AND public.can_read_execution(e.id) AND (e.scheduled_date=_date OR e.scheduled_date IS NULL OR (e.status NOT IN ('done','skipped','cancelled') AND e.due_time IS NOT NULL AND (e.scheduled_date+e.due_time)<(now() AT TIME ZONE 'America/Bogota')));
IF _date>today THEN SELECT result||coalesce(jsonb_agg(jsonb_build_object('id',r.id::text||':'||_date::text,'task_id',r.task_id,'scheduled_date',_date,'occurrence_date',_date,'due_time',r.due_time,'title',r.title,'description',r.description,'owner_id',r.owner_id,'creator_id',r.creator_id,'visible_to_creator',r.visible_to_creator,'priority',r.priority,'status','todo','recurring',true,'skip_state','none','projected',true)),'[]'::jsonb) INTO result FROM public.task_revisions r WHERE r.enabled AND r.recurrence<>'once' AND r.effective_from<=_date AND (r.effective_until IS NULL OR r.effective_until>=_date) AND (r.recurrence='daily' OR extract(dow FROM _date)::integer=ANY(r.weekdays)) AND (public.is_executive() OR r.owner_id=auth.uid() OR (r.visible_to_creator AND public.is_own_creator(r.creator_id))) AND NOT EXISTS(SELECT 1 FROM public.task_executions e WHERE e.task_id=r.task_id AND e.occurrence_date=_date AND e.status<>'cancelled'); END IF; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.task_execution_action(_id uuid,_action text,_body text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.task_executions; exec boolean := public.is_executive(); BEGIN
IF NOT public.is_active_member(auth.uid()) THEN RAISE EXCEPTION 'Not authorized'; END IF; SELECT * INTO e FROM public.task_executions WHERE id=_id FOR UPDATE; IF NOT FOUND OR NOT public.can_read_execution(_id) THEN RAISE EXCEPTION 'Not authorized'; END IF;
IF e.status='cancelled' OR e.archived_at IS NOT NULL THEN RAISE EXCEPTION 'Execution archived or cancelled'; END IF;
IF _action='comment' THEN IF nullif(trim(_body),'') IS NULL OR length(_body)>4000 THEN RAISE EXCEPTION 'Invalid comment'; END IF;
ELSIF _action='complete' THEN IF e.status IN ('done','skipped') THEN RETURN; END IF; IF e.scheduled_date>(now() AT TIME ZONE 'America/Bogota')::date THEN RAISE EXCEPTION 'Cannot complete future execution'; END IF; UPDATE public.task_executions SET status='done',completed_at=now(),skip_state='none' WHERE id=_id;
ELSIF _action='reopen' THEN IF e.status<>'done' THEN RAISE EXCEPTION 'Only completed executions can reopen'; END IF; UPDATE public.task_executions SET status='todo',skip_state='none' WHERE id=_id;
ELSIF _action='request_skip' THEN IF NOT e.recurring OR e.status IN ('done','skipped') OR e.skip_state='pending' THEN RAISE EXCEPTION 'Skip request not applicable'; END IF; UPDATE public.task_executions SET skip_state='pending',skip_reason=_body WHERE id=_id;
ELSIF _action IN ('approve_skip','reject_skip') THEN IF NOT exec OR e.skip_state<>'pending' THEN RAISE EXCEPTION 'Executive approval required'; END IF; UPDATE public.task_executions SET skip_state=CASE WHEN _action='approve_skip' THEN 'approved' ELSE 'rejected' END,status=CASE WHEN _action='approve_skip' THEN 'skipped' ELSE status END WHERE id=_id;
ELSE RAISE EXCEPTION 'Invalid action'; END IF;
INSERT INTO public.task_execution_events(execution_id,actor_id,action,body) VALUES(_id,auth.uid(),_action,_body);
IF NOT e.recurring AND _action IN ('complete','reopen') THEN UPDATE public.tasks SET status=CASE WHEN _action='complete' THEN 'done'::public.task_status ELSE 'todo'::public.task_status END WHERE id=e.task_id; END IF; END $$;
CREATE OR REPLACE FUNCTION public.task_resolve_execution(_task_id uuid,_date date) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.task_revisions; eid uuid; BEGIN
IF NOT public.is_active_member(auth.uid()) THEN RAISE EXCEPTION 'Not authorized'; END IF; PERFORM pg_advisory_xact_lock(7458321);
SELECT id INTO eid FROM public.task_executions WHERE task_id=_task_id AND occurrence_date=_date AND status<>'cancelled';
IF eid IS NOT NULL THEN IF NOT public.can_read_execution(eid) THEN RAISE EXCEPTION 'Not authorized'; END IF; RETURN eid; END IF;
SELECT * INTO r FROM public.task_revisions WHERE task_id=_task_id AND enabled AND recurrence<>'once' AND effective_from<=_date AND (effective_until IS NULL OR effective_until>=_date) AND (recurrence='daily' OR extract(dow FROM _date)::integer=ANY(weekdays)) ORDER BY created_at DESC LIMIT 1;
IF NOT FOUND OR NOT (public.is_executive() OR coalesce(r.owner_id=auth.uid(),false) OR (r.visible_to_creator AND public.is_own_creator(r.creator_id))) THEN RAISE EXCEPTION 'Not authorized'; END IF;
INSERT INTO public.task_executions(task_id,revision_id,scheduled_date,occurrence_date,due_time,title,description,owner_id,creator_id,priority,recurring,visible_to_creator) VALUES(r.task_id,r.id,_date,_date,r.due_time,r.title,r.description,r.owner_id,r.creator_id,r.priority,true,r.visible_to_creator) RETURNING id INTO eid; RETURN eid; END $$;
REVOKE ALL ON FUNCTION public.task_resolve_execution(uuid,date) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.task_future_action(_task_id uuid,_date date,_action text,_body text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE eid uuid; BEGIN
IF _action NOT IN ('comment','request_skip') OR _date<=(now() AT TIME ZONE 'America/Bogota')::date THEN RAISE EXCEPTION 'Invalid future action'; END IF;
eid:=public.task_resolve_execution(_task_id,_date); PERFORM public.task_execution_action(eid,_action,_body); RETURN eid; END $$;
CREATE OR REPLACE FUNCTION public.move_task_execution(_id uuid,_task_id uuid,_occurrence_date date,_time time,_date date DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.task_executions; eid uuid; target date; BEGIN
IF NOT public.is_active_member(auth.uid()) OR NOT public.is_executive() THEN RAISE EXCEPTION 'Executive required to reschedule'; END IF; IF _time IS NULL THEN RAISE EXCEPTION 'Choose an exact time'; END IF;
PERFORM pg_advisory_xact_lock(7458321); eid:=_id;
IF eid IS NULL THEN eid:=public.task_resolve_execution(_task_id,_occurrence_date); END IF;
SELECT * INTO e FROM public.task_executions WHERE id=eid FOR UPDATE;
IF NOT FOUND OR e.archived_at IS NOT NULL OR e.status IN ('done','skipped','cancelled') THEN RAISE EXCEPTION 'Execution cannot be moved'; END IF;
target:=coalesce(_date,e.scheduled_date); IF target IS NULL THEN RAISE EXCEPTION 'Choose a scheduled date'; END IF;
IF target=e.scheduled_date AND _time=e.due_time THEN RETURN eid; END IF;
IF EXISTS(SELECT 1 FROM public.task_executions WHERE id<>eid AND owner_id IS NOT DISTINCT FROM e.owner_id AND scheduled_date=target AND due_time=_time AND archived_at IS NULL AND status NOT IN ('cancelled','skipped')) THEN RAISE EXCEPTION 'Time already occupied for this owner; choose another time'; END IF;
UPDATE public.task_executions SET scheduled_date=target,due_time=_time WHERE id=eid;
INSERT INTO public.task_execution_events(execution_id,actor_id,action,body) VALUES(eid,auth.uid(),'rescheduled',jsonb_build_object('from_date',e.scheduled_date,'from_time',e.due_time,'to_date',target,'to_time',_time)::text); RETURN eid; END $$;
CREATE OR REPLACE FUNCTION public.archive_task_executions(_ids uuid[],_confirm_count integer,_completed_only boolean DEFAULT false) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.task_executions; n integer:=0; BEGIN
IF NOT public.is_active_member(auth.uid()) THEN RAISE EXCEPTION 'Not authorized'; END IF;
IF _ids IS NULL OR cardinality(_ids)=0 OR cardinality(_ids)>500 OR _confirm_count<>cardinality(_ids) OR (SELECT count(DISTINCT x) FROM unnest(_ids) x)<>_confirm_count THEN RAISE EXCEPTION 'Confirm the exact number of executions'; END IF;
IF (cardinality(_ids)>1 OR _completed_only) AND NOT public.is_executive() THEN RAISE EXCEPTION 'Executive required for bulk deletion'; END IF;
PERFORM pg_advisory_xact_lock(7458321);
FOR e IN SELECT * FROM public.task_executions WHERE id=ANY(_ids) ORDER BY id FOR UPDATE LOOP
IF e.archived_at IS NOT NULL OR (_completed_only AND e.status<>'done') THEN RAISE EXCEPTION 'Selection changed; review confirmation'; END IF;
IF NOT (public.is_executive() OR coalesce(e.owner_id=auth.uid(),false)) THEN RAISE EXCEPTION 'Not authorized'; END IF;
n:=n+1; END LOOP; IF n<>_confirm_count THEN RAISE EXCEPTION 'Selection changed; review confirmation'; END IF;
UPDATE public.task_executions SET archived_at=now() WHERE id=ANY(_ids);
INSERT INTO public.task_execution_events(execution_id,actor_id,action) SELECT id,auth.uid(),'archived' FROM public.task_executions WHERE id=ANY(_ids); RETURN n; END $$;
REVOKE ALL ON FUNCTION public.move_task_execution(uuid,uuid,date,time,date),public.archive_task_executions(uuid[],integer,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.move_task_execution(uuid,uuid,date,time,date),public.archive_task_executions(uuid[],integer,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.save_task_configuration(_task_id uuid,_config jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tid uuid; rid uuid; start_date date; effective date; today date := (now() AT TIME ZONE 'America/Bogota')::date; mode text; state text; days integer[]; affected uuid; visible boolean; oid uuid; cid uuid; BEGIN
IF NOT public.is_active_member(auth.uid()) OR NOT public.is_executive() THEN RAISE EXCEPTION 'Executive required'; END IF;
_task_id:=nullif(_task_id,'00000000-0000-0000-0000-000000000000'::uuid); PERFORM set_config('venusx.task_configuration','saving',true); PERFORM pg_advisory_xact_lock(7458321); PERFORM public.materialize_task_executions();
mode:=coalesce(_config->>'recurrence','once'); state:=coalesce(_config->>'recurrence_state','enabled'); SELECT coalesce(array_agg(value::integer),'{}') INTO days FROM jsonb_array_elements_text(coalesce(_config->'weekdays','[]'));
IF mode NOT IN ('once','daily','weekdays') OR state NOT IN ('enabled','paused','disabled') OR (mode='weekdays' AND cardinality(days)=0) OR EXISTS(SELECT 1 FROM unnest(days) d WHERE d<0 OR d>6) THEN RAISE EXCEPTION 'Invalid recurrence'; END IF;
IF nullif(trim(_config->>'title'),'') IS NULL OR length(_config->>'title')>200 THEN RAISE EXCEPTION 'Title required (maximum 200 characters)'; END IF;
start_date:=nullif(_config->>'due_date','')::date; IF mode<>'once' AND start_date IS NULL THEN RAISE EXCEPTION 'Recurring tasks need a start date'; END IF;
oid:=nullif(_config->>'owner_id','')::uuid; cid:=nullif(_config->>'creator_id','')::uuid; visible:=coalesce((_config->>'visible_to_creator')::boolean,false);
IF visible AND cid IS NULL THEN RAISE EXCEPTION 'Select a linked creator before publishing'; END IF;
IF oid IS NOT NULL AND NOT public.is_active_member(oid) THEN RAISE EXCEPTION 'Owner must be an active member'; END IF;
IF cid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.creators WHERE id=cid AND archived_at IS NULL) THEN RAISE EXCEPTION 'Creator not available'; END IF;
IF _task_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.tasks WHERE id=_task_id) THEN RAISE EXCEPTION 'Task not found'; END IF;
effective:=CASE WHEN _task_id IS NULL THEN greatest(coalesce(start_date,today),today) ELSE greatest(coalesce(start_date,today+1),today+1) END;
IF _task_id IS NULL THEN INSERT INTO public.tasks(title,description,owner_id,creator_id,visible_to_creator,priority,due_date,due_time,recurrence,weekdays,recurrence_state,created_by) VALUES(trim(_config->>'title'),_config->>'description',oid,cid,visible,coalesce(_config->>'priority','medium')::public.task_priority,start_date,nullif(_config->>'due_time','')::time,mode,days,state,auth.uid()) RETURNING id INTO tid;
ELSE tid:=_task_id; UPDATE public.task_revisions SET effective_until=least(coalesce(effective_until,effective-1),effective-1) WHERE task_id=tid;
FOR affected IN UPDATE public.task_executions SET status='cancelled' WHERE task_id=tid AND coalesce(occurrence_date,scheduled_date)>=effective AND status NOT IN ('done','skipped','cancelled') AND archived_at IS NULL RETURNING id LOOP INSERT INTO public.task_execution_events(execution_id,actor_id,action) VALUES(affected,auth.uid(),'configuration_superseded'); END LOOP;
UPDATE public.tasks SET title=trim(_config->>'title'),description=_config->>'description',owner_id=oid,creator_id=cid,visible_to_creator=visible,priority=coalesce(_config->>'priority','medium')::public.task_priority,due_date=start_date,due_time=nullif(_config->>'due_time','')::time,recurrence=mode,weekdays=days,recurrence_state=state WHERE id=tid; END IF;
INSERT INTO public.task_revisions(task_id,effective_from,title,description,owner_id,creator_id,visible_to_creator,priority,due_time,recurrence,weekdays,enabled) VALUES(tid,effective,trim(_config->>'title'),_config->>'description',oid,cid,visible,coalesce(_config->>'priority','medium')::public.task_priority,nullif(_config->>'due_time','')::time,mode,days,state='enabled') RETURNING id INTO rid;
IF mode='once' AND state='enabled' THEN INSERT INTO public.task_executions(task_id,revision_id,scheduled_date,occurrence_date,due_time,title,description,owner_id,creator_id,visible_to_creator,priority) SELECT task_id,id,CASE WHEN _task_id IS NULL THEN start_date ELSE effective END,CASE WHEN _task_id IS NULL THEN start_date ELSE effective END,due_time,title,description,owner_id,creator_id,visible_to_creator,priority FROM public.task_revisions WHERE id=rid; END IF; RETURN tid; END $$;
CREATE OR REPLACE FUNCTION public.task_new_execution() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rid uuid; BEGIN
IF current_setting('venusx.task_configuration',true)='saving' THEN RETURN NEW; END IF;
INSERT INTO public.task_revisions(task_id,effective_from,title,description,owner_id,creator_id,visible_to_creator,priority,due_time,recurrence,enabled) VALUES(NEW.id,coalesce(NEW.due_date,(now() AT TIME ZONE 'America/Bogota')::date),NEW.title,NEW.description,NEW.owner_id,NEW.creator_id,NEW.visible_to_creator,NEW.priority,NEW.due_time,'once',NEW.archived_at IS NULL) RETURNING id INTO rid;
INSERT INTO public.task_executions(task_id,revision_id,scheduled_date,occurrence_date,due_time,title,description,owner_id,creator_id,visible_to_creator,priority,status,completed_at) VALUES(NEW.id,rid,NEW.due_date,NEW.due_date,NEW.due_time,NEW.title,NEW.description,NEW.owner_id,NEW.creator_id,NEW.visible_to_creator,NEW.priority,NEW.status::text,NEW.completed_at); RETURN NEW; END $$;